import numpy as np
def layernorm(x, eps=1e-5):                     # γ=1, β=0 으로 둔 LayerNorm
    mu = x.mean(-1, keepdims=True); var = x.var(-1, keepdims=True)
    return (x - mu) / np.sqrt(var + eps)
def mhsa(X, W, H):
    N, D = X.shape; Dh = D // H
    Q, K, V = (np.moveaxis((X @ W[i]).reshape(N, H, Dh), 1, 0) for i in range(3))
    E = Q @ K.transpose(0, 2, 1) / np.sqrt(Dh)
    A = np.exp(E - E.max(-1, keepdims=True)); A /= A.sum(-1, keepdims=True)
    return np.moveaxis(A @ V, 0, 1).reshape(N, D) @ W[3]
def block(X, p, H=4):                           # 슬라이드 순서(post-norm)
    X = layernorm(X + mhsa(X, p["attn"], H))    # 셀프 어텐션 → 잔차 → LN
    return layernorm(X + np.maximum(0, X @ p["W1"]) @ p["W2"])   # MLP → 잔차 → LN
rng = np.random.default_rng(0)
N, D, L = 6, 32, 12
def init():
    return {"attn": [rng.normal(size=(D, D)) / np.sqrt(D) for _ in range(4)],
            "W1": rng.normal(size=(D, 4 * D)) / np.sqrt(D),
            "W2": rng.normal(size=(4 * D, D)) / np.sqrt(4 * D)}
params = [init() for _ in range(L)]             # 블록마다 다른 가중치
X = rng.normal(size=(N, D))
for p in params: X = block(X, p)
print(X.shape, "블록 하나(LN·편향 제외)", 4 * D * D + 8 * D * D, "= 12·D² =", 12 * D * D)
